// Number of complex values: 1024
// Total floats: 2048
// Memory usage: 8192 bytes
const size_t twiddles_count_2048 = 1024;

const float* get_twiddle_table(int N, int* num_complex) {
    switch(N) {
        case 128:  *num_complex = twiddles_count_128;   return twiddles_128;
        case 256:  *num_complex = twiddles_count_256;  return twiddles_256;
        case 512:  *num_complex = twiddles_count_512;  return twiddles_512;
        case 1024: *num_complex = twiddles_count_1024;  return twiddles_1024;
        case 1536: *num_complex = twiddles_count_1536; return twiddles_1536;
        case 2048: *num_complex = twiddles_count_2048; return twiddles_2048;
        default:   *num_complex = 0;    return NULL;
    }
}

